create table if not exists damas_private.entsoe_profiles(id integer primary key,name text unique not null,parameters jsonb not null,schedule text not null,event boolean not null);
alter table damas_private.entsoe_profiles enable row level security;
create table if not exists public.entsoe_documents(dataset text not null,delivery_date date not null,document_xml text not null,collected_at timestamptz not null default now(),primary key(dataset,delivery_date));
alter table public.entsoe_documents enable row level security;
create policy entsoe_public_read on public.entsoe_documents for select to anon,authenticated using(true);
grant select on public.entsoe_documents to anon,authenticated;
create table if not exists public.entsoe_runs(id bigint generated always as identity primary key,dataset text not null,delivery_date date not null,status text not null,finished_at timestamptz not null default now(),series_count integer,error_message text);
alter table public.entsoe_runs enable row level security;
create policy entsoe_runs_public_read on public.entsoe_runs for select to anon,authenticated using(true);
grant select on public.entsoe_runs to anon,authenticated;
create table if not exists damas_private.entsoe_queue(dataset text not null,delivery_date date not null,attempted_at timestamptz,finished_at timestamptz,primary key(dataset,delivery_date));
alter table damas_private.entsoe_queue enable row level security;
create or replace function public.sync_entsoe_document(p_name text,p_day date) returns text language plpgsql security definer set search_path=pg_catalog,public,extensions as $$
declare p record;token text;url text;kv record;r record;x xml;cnt integer; a timestamptz;b timestamptz;
begin
 select * into strict p from damas_private.entsoe_profiles where name=p_name;
 select decrypted_secret into token from vault.decrypted_secrets where name='entsoe_token';
 if token is null then raise exception 'Missing Vault token';end if;
 a:=p_day::timestamp at time zone 'Europe/Bucharest';b:=(p_day+1)::timestamp at time zone 'Europe/Bucharest';
 if p.schedule='annual' then a:=make_date(extract(year from p_day)::integer,1,1)::timestamp at time zone 'Europe/Bucharest';b:=(make_date(extract(year from p_day)::integer+1,1,1))::timestamp at time zone 'Europe/Bucharest';end if;
 url:='https://web-api.tp.entsoe.eu/api?securityToken='||extensions.urlencode(token)||'&periodStart='||to_char(a at time zone 'UTC','YYYYMMDDHH24MI')||'&periodEnd='||to_char(b at time zone 'UTC','YYYYMMDDHH24MI');
 for kv in select * from jsonb_each_text(p.parameters) loop url:=url||'&'||extensions.urlencode(kv.key)||'='||extensions.urlencode(kv.value);end loop;
 begin
 perform extensions.http_set_curlopt('CURLOPT_TIMEOUT_MS','30000');
 select * into r from extensions.http_get(url);
 if r.status not in (200,400) then raise exception 'Unexpected HTTP status';end if;
 x:=xmlparse(document r.content);
 if r.content like '%Acknowledgement_MarketDocument%' then
 if r.content ~* 'no matching data|no data found' then insert into public.entsoe_runs(dataset,delivery_date,status,series_count) values(p_name,p_day,'not_published',0);return 'not_published';else raise exception 'API acknowledgement error';end if;
 end if;
 cnt:=array_length(xpath('//*[local-name()="TimeSeries"]',x),1);
 if cnt is null or cnt=0 then raise exception 'No TimeSeries';end if;
 exception when others then insert into public.entsoe_runs(dataset,delivery_date,status,error_message) values(p_name,p_day,'error','Request or document validation failed; previous document retained');return 'error';end;
end $$;
revoke all on function public.sync_entsoe_document(text,date) from public,anon,authenticated;
create or replace function public.tick_entsoe() returns void language plpgsql security definer set search_path=pg_catalog,public as $$
declare p record;q record;result text;slot integer;
begin
 if not pg_try_advisory_xact_lock(71386426) then return;end if;
 slot:=mod(floor(extract(epoch from now())/60)::bigint,(select count(*) from damas_private.entsoe_profiles))::integer;
 select * into p from damas_private.entsoe_profiles where id=slot;
 perform public.sync_entsoe_document(p.name,(now() at time zone 'Europe/Bucharest')::date);
 select * into q from damas_private.entsoe_queue where finished_at is null order by attempted_at nulls first,delivery_date,dataset limit 1;
 if found then result:=public.sync_entsoe_document(q.dataset,q.delivery_date);update damas_private.entsoe_queue set attempted_at=now(),finished_at=case when result in ('ok','not_published') then now() else null end where dataset=q.dataset and delivery_date=q.delivery_date;end if;
end $$;
revoke all on function public.tick_entsoe() from public,anon,authenticated;
select cron.schedule('entsoe-documents-minute','* * * * *','select public.tick_entsoe();');
select public.sync_entsoe_document('load_actual','2026-10-10');
